44	NVCV_TEST_SUITE_P(OpFlip, test::ValueList<int, int, int, NVCVImageFormat, int>
45	{
46	    // width, height, batches,                  format, flipCode
47	    {    176,    113,       1,    NVCV_IMAGE_FORMAT_U8,  0},
48	    {    123,     66,       5,    NVCV_IMAGE_FORMAT_U8,  1},
49	    {    123,     33,       3,  NVCV_IMAGE_FORMAT_RGB8, -1},
50	    {     42,     53,       4, NVCV_IMAGE_FORMAT_RGBA8,  1},
51	    {     13,     42,       3,  NVCV_IMAGE_FORMAT_RGB8,  0},
52	    {     62,    111,       4, NVCV_IMAGE_FORMAT_RGBA8, -1},
53	    // Float3 is intentionally routed through conservative kernels. Cover every flip direction for
54	    // both tensor and var-shape submissions against the independent CPU reference.
55	    {     67,     45,       2, NVCV_IMAGE_FORMAT_RGBf32,  1},
56	    {     70,     43,       3, NVCV_IMAGE_FORMAT_RGBf32,  0},
57	    {     65,     41,       2, NVCV_IMAGE_FORMAT_RGBf32, -1},
58	    // Single-channel cases that exercise the wide (VEC=4) vectorized path and its in-register lane
59	    // reversal: width divisible by 4 (vector body) for each flip code, plus a non-divisible width that
60	    // falls back to the scalar single-channel tail. U8 and U16 cover both VEC lane widths.
61	    {    256,     65,       2,    NVCV_IMAGE_FORMAT_U8,  1}, // wide horizontal (lane reversal)
62	    {    256,     64,       2,    NVCV_IMAGE_FORMAT_U8, -1}, // wide both (lane reversal)
63	    {    256,     48,       3,    NVCV_IMAGE_FORMAT_U8,  0}, // wide vertical (direct copy)
64	    {    128,     40,       2,   NVCV_IMAGE_FORMAT_U16, -1}, // wide both, 16-bit lanes
65	    {    255,     40,       2,    NVCV_IMAGE_FORMAT_U8, -1}  // scalar tail (width % 4 != 0)
66	});
