70	TEST_P(OpFlip, correct_output)
71	{
72	    cudaStream_t stream;
73	    ASSERT_EQ(cudaSuccess, cudaStreamCreate(&stream));
74	
75	    int width   = GetParamValue<0>();
76	    int height  = GetParamValue<1>();
77	    int batches = GetParamValue<2>();
78	
79	    nvcv::ImageFormat format{GetParamValue<3>()};
80	
81	    int flipCode = GetParamValue<4>();
82	
83	    int3 shape{width, height, batches};
84	
85	    nvcv::Tensor inTensor  = nvcv::util::CreateTensor(batches, width, height, format);
86	    nvcv::Tensor outTensor = nvcv::util::CreateTensor(batches, width, height, format);
87	
88	    auto input  = inTensor.exportData<nvcv::TensorDataStridedCuda>();
89	    auto output = outTensor.exportData<nvcv::TensorDataStridedCuda>();
90	
91	    ASSERT_NE(input, nullptr);
92	    ASSERT_NE(output, nullptr);
93	
94	    auto inAccess = nvcv::TensorDataAccessStridedImagePlanar::Create(*input);
95	    ASSERT_TRUE(inAccess);
96	
97	    auto outAccess = nvcv::TensorDataAccessStridedImagePlanar::Create(*output);
98	    ASSERT_TRUE(outAccess);
99	
100	    long inSampleStride  = inAccess->numRows() * inAccess->rowStride();
101	    long outSampleStride = outAccess->numRows() * outAccess->rowStride();
102	
103	    auto inBufSize  = static_cast<size_t>(inSampleStride * inAccess->numSamples());
104	    auto outBufSize = static_cast<size_t>(outSampleStride * outAccess->numSamples());
105	
106	    long3 inStrides{inSampleStride, inAccess->rowStride(), inAccess->colStride()};
107	    long3 outStrides{outSampleStride, outAccess->rowStride(), outAccess->colStride()};
108	
109	    std::vector<uint8_t> inVec(inBufSize);
110	
111	    std::default_random_engine    randEng(0);
112	    std::uniform_int_distribution rand(0u, 255u);
113	
114	    std::ranges::generate(inVec, [&rand, &randEng]() { return rand(randEng); });
115	    std::vector<uint8_t> goldVec(outBufSize);
116	    test::FlipCPU(goldVec, outStrides, inVec, inStrides, shape, format, flipCode);
117	
118	    // copy random input to device
119	    ASSERT_EQ(cudaSuccess, cudaMemcpy(input->basePtr(), inVec.data(), inBufSize, cudaMemcpyHostToDevice));
120	
121	    // run operator
122	    cvcuda::Flip flipOp;
123	    EXPECT_NO_THROW(flipOp(stream, inTensor, outTensor, flipCode));
124	
125	    ASSERT_EQ(cudaSuccess, cudaStreamSynchronize(stream));
126	    ASSERT_EQ(cudaSuccess, cudaStreamDestroy(stream));
127	
128	    // copy output back to host
129	    std::vector<uint8_t> testVec(outBufSize);
130	    ASSERT_EQ(cudaSuccess, cudaMemcpy(testVec.data(), output->basePtr(), outBufSize, cudaMemcpyDeviceToHost));
131	
132	    EXPECT_EQ(testVec, goldVec);
133	}
