135	TEST_P(OpFlip, varshape_correct_output)
136	{
137	    cudaStream_t stream;
138	    ASSERT_EQ(cudaSuccess, cudaStreamCreate(&stream));
139	
140	    int width   = GetParamValue<0>();
141	    int height  = GetParamValue<1>();
142	    int batches = GetParamValue<2>();
143	
144	    nvcv::ImageFormat format{GetParamValue<3>()};
145	
146	    int flipCode = GetParamValue<4>();
147	
148	    // Create input varshape
149	    std::default_random_engine    rng;
150	    std::uniform_int_distribution udistWidth(ScaledSize(width, 0.8), ScaledSize(width, 1.1));
151	    std::uniform_int_distribution udistHeight(ScaledSize(height, 0.8), ScaledSize(height, 1.1));
152	
153	    std::vector<nvcv::Image> imgSrc;
154	
155	    std::vector<std::vector<uint8_t>> srcVec(batches);
156	    std::vector<int>                  srcVecRowStride(batches);
157	
158	    for (int i = 0; i < batches; ++i)
159	    {
160	        imgSrc.emplace_back(nvcv::Size2D{udistWidth(rng), udistHeight(rng)}, format);
161	
162	        int srcRowStride   = imgSrc[i].size().w * format.planePixelStrideBytes(0);
163	        srcVecRowStride[i] = srcRowStride;
164	
165	        std::uniform_int_distribution<uint8_t> udist(0, 255);
166	
167	        srcVec[i].resize(imgSrc[i].size().h * srcRowStride);
168	        std::ranges::generate(srcVec[i], [&udist, &rng]() { return udist(rng); });
169	
170	        auto imgData = imgSrc[i].exportData<nvcv::ImageDataStridedCuda>();
171	        ASSERT_NE(imgData, nvcv::NullOpt);
172	
173	        // Copy input data to the GPU
174	        ASSERT_EQ(cudaSuccess,
175	                  cudaMemcpy2DAsync(imgData->plane(0).basePtr, imgData->plane(0).rowStride, srcVec[i].data(),
176	                                    srcRowStride, srcRowStride, imgSrc[i].size().h, cudaMemcpyHostToDevice, stream));
177	    }
178	
179	    nvcv::ImageBatchVarShape batchSrc(batches);
180	    batchSrc.pushBack(imgSrc.begin(), imgSrc.end());
181	
182	    // Create output varshape
183	    std::vector<nvcv::Image> imgDst;
184	    for (int i = 0; i < batches; ++i)
185	    {
186	        imgDst.emplace_back(imgSrc[i].size(), imgSrc[i].format());
187	    }
188	    nvcv::ImageBatchVarShape batchDst(batches);
189	    batchDst.pushBack(imgDst.begin(), imgDst.end());
190	
191	    // Create flip code tensor
192	    nvcv::Tensor flip_code({{batches}, "N"}, nvcv::TYPE_S32);
193	    {
194	        auto dev = flip_code.exportData<nvcv::TensorDataStridedCuda>();
195	        ASSERT_NE(dev, nullptr);
196	
197	        std::vector<int> vec(batches, flipCode);
198	
199	        ASSERT_EQ(cudaSuccess, cudaMemcpyAsync(dev->basePtr(), vec.data(), vec.size() * sizeof(int),
200	                                               cudaMemcpyHostToDevice, stream));
201	    }
202	
203	    // Run operator
204	    cvcuda::Flip flipOp(batches);
205	
206	    EXPECT_NO_THROW(flipOp(stream, batchSrc, batchDst, flip_code));
207	
208	    ASSERT_EQ(cudaSuccess, cudaStreamSynchronize(stream));
209	    ASSERT_EQ(cudaSuccess, cudaStreamDestroy(stream));
210	
211	    // Check test data against gold
212	    for (int i = 0; i < batches; ++i)
213	    {
214	        SCOPED_TRACE(i);
215	
216	        const auto srcData = imgSrc[i].exportData<nvcv::ImageDataStridedCuda>();
217	        ASSERT_EQ(srcData->numPlanes(), 1);
218	
219	        const auto dstData = imgDst[i].exportData<nvcv::ImageDataStridedCuda>();
220	        ASSERT_EQ(dstData->numPlanes(), 1);
221	
222	        int dstRowStride = srcVecRowStride[i];
223	
224	        int3  shape{srcData->plane(0).width, srcData->plane(0).height, 1};
225	        long3 pitches{shape.y * dstRowStride, dstRowStride, format.planePixelStrideBytes(0)};
226	
227	        std::vector<uint8_t> testVec(shape.y * pitches.y);
228	
229	        // Copy output data to Host
230	        ASSERT_EQ(cudaSuccess,
231	                  cudaMemcpy2D(testVec.data(), dstRowStride, dstData->plane(0).basePtr, dstData->plane(0).rowStride,
232	                               dstRowStride, shape.y, cudaMemcpyDeviceToHost));
233	
234	        // Generate gold result
235	        std::vector<uint8_t> goldVec(shape.y * pitches.y);
236	        test::FlipCPU(goldVec, pitches, srcVec[i], pitches, shape, format, flipCode);
237	
238	        EXPECT_EQ(testVec, goldVec);
239	    }
240	}
