242	// =============================================================================
243	// Planar (NCHW/CHW) layout support
244	//
245	// Flip remaps each pixel independently of its channel, so a planar input is flipped plane-by-plane
246	// and must produce exactly the same pixels as the interleaved path. These tests feed identical data
247	// in both layouts through cvcuda::Flip and require the (re-interleaved) planar output to match the
248	// interleaved output bit-for-bit, for every dtype and flip code.
249	// =============================================================================
250	
251	namespace {
252	
253	// Flip identical data in interleaved and planar tensor layout; outputs must match bit-for-bit.
254	// The shared scaffolding (upload/run/download/compare) lives in PlanarParityUtils.hpp; here we only
255	// bind the Flip call.
256	void RunPlanarParityTensorCase(nvcv::ImageFormat planarFmt, nvcv::ImageFormat interleavedFmt, int w, int h,
257	                               int flipCode, int numImages)
258	{
259	    test::planar::RunTensorParity(
260	        planarFmt, interleavedFmt, w, h, w, h, numImages,
261	        [numImages, flipCode](cudaStream_t s, const nvcv::Tensor &src, const nvcv::Tensor &dst, nvcv::ImageFormat)
262	        {
263	            cvcuda::Flip op(numImages);
264	            EXPECT_NO_THROW(op(s, src, dst, flipCode));
265	        });
266	}
267	
268	// Var-shape counterpart of RunPlanarParityTensorCase.
269	void RunPlanarParityVarShapeCase(nvcv::ImageFormat planarFmt, nvcv::ImageFormat interleavedFmt, int w, int h,
270	                                 int flipCode, int numImages)
271	{
272	    // Var-shape Flip takes the flip code as a per-image tensor; upload it once (synchronously, so it
273	    // is ready before the operator runs on the parity helper's stream).
274	    nvcv::Tensor flip_code({{numImages}, "N"}, nvcv::TYPE_S32);
275	    {
276	        auto dev = flip_code.exportData<nvcv::TensorDataStridedCuda>();
277	        ASSERT_NE(dev, nullptr);
278	        std::vector<int> vec(numImages, flipCode);
279	        ASSERT_EQ(cudaSuccess,
280	                  cudaMemcpy(dev->basePtr(), vec.data(), vec.size() * sizeof(int), cudaMemcpyHostToDevice));
281	    }
282	
283	    test::planar::RunVarShapeParity(planarFmt, interleavedFmt, w, h, w, h, numImages,
284	                                    [numImages, &flip_code](cudaStream_t s, const nvcv::ImageBatchVarShape &src,
285	                                                            const nvcv::ImageBatchVarShape &dst, nvcv::ImageFormat)
286	                                    {
287	                                        cvcuda::Flip op(numImages);
288	                                        EXPECT_NO_THROW(op(s, src, dst, flip_code));
289	                                    });
290	}
291	
292	} // namespace
