    for (const auto &[inputFmtExtra, outputFmtExtra] : testSet)
    {
        std::vector<nvcv::Image> imgSrc;
        for (int i = 0; i < batches - 1; ++i)
        {
            imgSrc.emplace_back(nvcv::Size2D{udistWidth(rng), udistHeight(rng)}, fmt);
